from __future__ import annotations

__all__ = ["fizzbuzz"]


def fizzbuzz(n: int) -> list[str]:
    """Return the FizzBuzz sequence for 1..n as a new list of strings.

    Raises TypeError if n is not an int (bool is rejected too).
    Returns an empty list when n <= 0.
    """
    if not isinstance(n, int) or isinstance(n, bool):
        raise TypeError(f"n must be int, not {type(n).__name__}")

    result: list[str] = []
    for i in range(1, n + 1):
        if i % 15 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

from __future__ import annotations

import unittest

from fizzbuzz import fizzbuzz


def expected(i: int) -> str:
    if i % 15 == 0:
        return "FizzBuzz"
    if i % 3 == 0:
        return "Fizz"
    if i % 5 == 0:
        return "Buzz"
    return str(i)


class FizzBuzzTests(unittest.TestCase):
    def test_non_positive_returns_empty(self) -> None:
        self.assertEqual(fizzbuzz(0), [])
        self.assertEqual(fizzbuzz(-7), [])

    def test_one(self) -> None:
        self.assertEqual(fizzbuzz(1), ["1"])

    def test_ends_with_buzz_and_fizz(self) -> None:
        self.assertTrue(fizzbuzz(5)[-1].endswith("Buzz"))
        self.assertTrue(fizzbuzz(3)[-1].endswith("Fizz"))

    def test_fifteen_last_is_fizzbuzz(self) -> None:
        self.assertEqual(fizzbuzz(15)[-1], "FizzBuzz")

    def test_fifteen_full_list(self) -> None:
        self.assertEqual(
            fizzbuzz(15),
            ["1", "2", "Fizz", "4", "Buzz", "Fizz", "7", "8", "Fizz", "Buzz",
             "11", "Fizz", "13", "14", "FizzBuzz"],
        )

    def test_length_matches_n(self) -> None:
        for n in (1, 2, 7, 14, 15, 16, 99, 100, 101, 250):
            with self.subTest(n=n):
                self.assertEqual(len(fizzbuzz(n)), n)

    def test_every_index_up_to_100(self) -> None:
        result = fizzbuzz(100)
        for i in range(1, 101):
            with self.subTest(i=i):
                self.assertEqual(result[i - 1], expected(i))

    def test_thirty_fizzbuzz_positions(self) -> None:
        result = fizzbuzz(30)
        self.assertEqual(result[14], "FizzBuzz")
        self.assertEqual(result[29], "FizzBuzz")

    def test_returns_new_list_each_call(self) -> None:
        a = fizzbuzz(5)
        b = fizzbuzz(5)
        self.assertEqual(a, b)
        self.assertIsNot(a, b)
        a.append("mutated")
        self.assertEqual(fizzbuzz(5), ["1", "2", "Fizz", "4", "Buzz"])

    def test_rejects_non_int(self) -> None:
        for bad in ("5", 2.0, True, False, None, [3]):
            with self.subTest(value=bad):
                with self.assertRaises(TypeError):
                    fizzbuzz(bad)  # type: ignore[arg-type]


if __name__ == "__main__":
    unittest.main()
